import os, re, subprocess, tempfile, zipfile, glob
from collections import defaultdict

def extract_text_pdf(path, max_pages=2):
    # Use pdftotext to extract first pages
    with tempfile.NamedTemporaryFile(delete=False) as tmp:
        tmp_path = tmp.name
    try:
        subprocess.run([
            'pdftotext', '-f', '1', '-l', str(max_pages), '-layout', path, tmp_path
        ], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        with open(tmp_path, 'r', errors='ignore') as f:
            return f.read()
    finally:
        try:
            os.remove(tmp_path)
        except OSError:
            pass

def extract_text_docx(path):
    try:
        with zipfile.ZipFile(path) as z:
            xml = z.read('word/document.xml')
    except Exception:
        return ''
    # crude text extraction
    text = re.sub(b'<[^>]+>', b' ', xml)
    return text.decode(errors='ignore')

def extract_text_pptx(path):
    texts = []
    try:
        with zipfile.ZipFile(path) as z:
            for name in sorted([n for n in z.namelist() if n.startswith('ppt/slides/slide') and n.endswith('.xml')]):
                xml = z.read(name)
                text = re.sub(b'<[^>]+>', b' ', xml)
                texts.append(text.decode(errors='ignore'))
    except Exception:
        return ''
    return ' '.join(texts)

categories = {
    'LLM': [
        r'large language model', r'language model', r'LLM', r'transformer', r'GPT', r'BERT',
        r'prompt', r'prompting', r'pretrain', r'fine[- ]tune', r'instruction tuning',
        r'token', r'attention mechanism', r'self-attention', r'chatgpt', r'foundation model'
    ],
    'trapped_ion_and_qc': [
        r'trapped ion', r'ion trap', r'paul trap', r'penning trap', r'quantum computing',
        r'quantum computer', r'qubit', r'quantum gate', r'quantum circuit', r'quantum error',
        r'quantum simulation', r'quantum algorithm', r'rydberg', r'superposition', r'entanglement'
    ],
    'black_hole': [
        r'black hole', r'event horizon', r'schwarzschild', r'kerr', r'hawking', r'singularity',
        r'gravitational wave', r'accretion', r'astro-?ph', r'general relativity', r'bh\b'
    ],
    'DNA': [
        r'\bDNA\b', r'genome', r'genetic', r'chromosome', r'nucleotide', r'base pair',
        r'genomics', r'sequencing', r'CRISPR', r'RNA', r'polymerase', r'PCR'
    ],
    'music_history': [
        r'music', r'musicology', r'composer', r'symphony', r'opera', r'jazz', r'blues',
        r'baroque', r'romantic', r'classical', r'renaissance', r'folk music', r'concert'
    ]
}

compiled = {cat: [re.compile(pat, re.I) for pat in pats] for cat, pats in categories.items()}

def score_text(text):
    scores = {}
    for cat, patterns in compiled.items():
        s = 0
        for pat in patterns:
            s += len(pat.findall(text))
        scores[cat] = s
    return scores

root = '/root/papers/all'
files = [os.path.join(root, f) for f in os.listdir(root) if os.path.isfile(os.path.join(root, f))]

results = []
for path in sorted(files):
    ext = os.path.splitext(path)[1].lower()
    if ext == '.pdf':
        text = extract_text_pdf(path)
    elif ext == '.docx':
        text = extract_text_docx(path)
    elif ext == '.pptx':
        text = extract_text_pptx(path)
    else:
        text = ''
    scores = score_text(text)
    results.append((path, scores))

# show top scores and low-confidence
for path, scores in results[:5]:
    pass

# write summary to tmp
out_path = '/tmp/classification_scores.tsv'
with open(out_path, 'w') as f:
    f.write('file\t' + '\t'.join(categories.keys()) + '\n')
    for path, scores in results:
        f.write(os.path.basename(path))
        for cat in categories.keys():
            f.write('\t' + str(scores.get(cat,0)))
        f.write('\n')

print(out_path)
